void abort(void);
void exit(int);

void put_field(unsigned int start, unsigned int len) {
  int cur_bitshift = ((start + len) % 8) - 8;
  if (cur_bitshift > -8)
    exit(0);
}

int main() {
  put_field(0, 1);
  abort();
}


